import subprocess, pathlib
root = pathlib.Path(r'C:\Users\eric_rash\Desktop\DEV')
cands = [root]
for base in [root, root / 'Football', root / 'SpecialRequests']:
    if base.is_dir():
        cands += [p for p in base.iterdir() if p.is_dir() and (p / '.git').exists()]
home = pathlib.Path.home() / '.claude'
cands += [home, home / 'skills', home / 'global-memory']
seen = set()
for r in cands:
    if r in seen: continue
    seen.add(r)
    def g(*a):
        return subprocess.run(['git', '-C', str(r), *a], capture_output=True, text=True, encoding='utf-8', errors='replace').stdout.strip()
    dirty = g('status', '--porcelain')
    ahead = g('rev-list', '--count', '@{u}..HEAD') if g('rev-parse', '--abbrev-ref', '@{u}') else 'no-upstream'
    if dirty or (ahead not in ('0',)):
        n = len(dirty.splitlines()) if dirty else 0
        print(f'{r}: dirty={n} ahead={ahead}')
        for line in dirty.splitlines()[:6]: print('    ', line)
print('checked', len(seen))

